# Lesson 3, parts 5 and 6, sources.
# Figures of the math exercises are checked here, so a typo stops the build.
# t-1, Long Put: K 80, p 5
assert max(80 - 72, 0) - 5 == 3 and 80 - 5 == 75 and 80 - 5 - 12 == 63 and max(80 - 0, 0) - 5 == 75
# t-2, Short Call: K 60, c 4
assert 4 - max(70 - 60, 0) == -6 and 4 - max(55 - 60, 0) == 4 and 60 + 4 == 64
# t-4, three index calls: K 4,300, c 40 points, 50 ש״ח a point
assert 40 * 50 * 3 == 6000 and max(4420 - 4300, 0) == 120 and (120 - 40) * 50 * 3 == 12000 and 4300 + 40 == 4340
# t-5, ten dollar puts: K 3.60, p 0.05, 10,000 dollars an option
assert round(0.05 * 10000 * 10) == 5000 and round(max(3.60 - 3.40, 0), 2) == 0.20 and round((0.20 - 0.05) * 10000 * 10) == 15000 and round(3.60 - 0.05, 2) == 3.55
# t-6, one index future: 3,000 points, 50 ש״ח a point, margin 15,000
assert 3000 * 50 == 150000 and 150000 / 15000 == 10 and 150000 * 0.01 == 1500 and 1500 / 15000 == 0.10
# homework questions
assert (120 - 105) - 7 == 8 and 4 - (60 - 50) == -6 and 200 + 15 + 25 == 240 and 50 + 6 == 56
assert 3000 * 50 * 2 * 0.01 == 3000 and 3000 / 30000 == 0.10 and round(0.6 * 90 + 0.4 * 110) == 98 and round(0.4 * 90 + 0.6 * 110) == 102
assert ((4100 - 4000) - 30) * 50 * 3 == 10500
assert 45 * 50 * 3 == 6750 and 3800 + 45 == 3845 and 2500 * 50 == 125000 and 125000 * 0.10 == 12500 and 125000 * -0.08 / 12500 == -0.8


