       + '<tr><td>' + TX('<b>נקודת איזון (Break-even)</b>') + '</td>' + ''.join(f'<td>{TX(x)}</td>' for x in ['$K + c$', '$K + c$', '$K − p$', '$K − p$']) + '</tr>'
